const fs = require('fs');
const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/);
let ptr = 0;

const N = +data[ptr++];
const B = +data[ptr++];

const edges = new Array(B);
for (let i = 0; i < B; i++) {
  const u = +data[ptr++];
  const v = +data[ptr++];
  const p = +data[ptr++];
  edges[i] = [u, v, p];
}

edges.sort((a, b) => b[2] - a[2]);

const dsu = new Int32Array(N + 1);
const sz = new Int32Array(N + 1);
for (let i = 1; i <= N; i++) {
  dsu[i] = i;
  sz[i] = 1;
}

function find(x) {
  while (dsu[x] !== x) {
    dsu[x] = dsu[dsu[x]];
    x = dsu[x];
  }
  return x;
}

function union(a, b) {
  a = find(a);
  b = find(b);
  if (a === b) return false;
  if (sz[a] < sz[b]) {
    const t = a;
    a = b;
    b = t;
  }
  dsu[b] = a;
  sz[a] += sz[b];
  return true;
}

const head = new Int32Array(N + 1).fill(-1);
const to = new Int32Array(2 * (N - 1) + 5);
const nxt = new Int32Array(2 * (N - 1) + 5);
const wt = new Int32Array(2 * (N - 1) + 5);
let edgeIdx = 0;

function addEdge(u, v, w) {
  to[edgeIdx] = v;
  wt[edgeIdx] = w;
  nxt[edgeIdx] = head[u];
  head[u] = edgeIdx++;

  to[edgeIdx] = u;
  wt[edgeIdx] = w;
  nxt[edgeIdx] = head[v];
  head[v] = edgeIdx++;
}

let added = 0;
for (let i = 0; i < B && added < N - 1; i++) {
  const e = edges[i];
  if (union(e[0], e[1])) {
    addEdge(e[0], e[1], e[2]);
    added++;
  }
}

const LOG = Math.ceil(Math.log2(N)) + 1;
const up = Array.from({ length: LOG }, () => new Int32Array(N + 1));
const mn = Array.from({ length: LOG }, () => new Int32Array(N + 1));
const depth = new Int32Array(N + 1);
const INF = 1000000000;

for (let i = 1; i <= N; i++) {
  up[0][i] = i;
  mn[0][i] = INF;
}

const queue = new Int32Array(N);
let qh = 0;
let qt = 0;
queue[qt++] = 1;
depth[1] = 0;
up[0][1] = 1;
mn[0][1] = INF;

while (qh < qt) {
  const v = queue[qh++];
  for (let e = head[v]; e !== -1; e = nxt[e]) {
    const u = to[e];
    if (u === up[0][v]) continue;
    up[0][u] = v;
    mn[0][u] = wt[e];
    depth[u] = depth[v] + 1;
    queue[qt++] = u;
  }
}

for (let k = 1; k < LOG; k++) {
  const upPrev = up[k - 1];
  const mnPrev = mn[k - 1];
  const upCur = up[k];
  const mnCur = mn[k];

  for (let v = 1; v <= N; v++) {
    const mid = upPrev[v];
    upCur[v] = upPrev[mid];
    const a = mnPrev[v];
    const b = mnPrev[mid];
    mnCur[v] = a < b ? a : b;
  }
}

const C = +data[ptr++];
const out = [];

for (let i = 0; i < C; i++) {
  let x = +data[ptr++];
  let y = +data[ptr++];
  let ans = INF;

  if (depth[x] < depth[y]) {
    const t = x;
    x = y;
    y = t;
  }

  let diff = depth[x] - depth[y];
  for (let k = 0; k < LOG; k++) {
    if (diff & (1 << k)) {
      const val = mn[k][x];
      if (val < ans) ans = val;
      x = up[k][x];
    }
  }

  if (x !== y) {
    for (let k = LOG - 1; k >= 0; k--) {
      if (up[k][x] !== up[k][y]) {
        const val1 = mn[k][x];
        const val2 = mn[k][y];
        if (val1 < ans) ans = val1;
        if (val2 < ans) ans = val2;
        x = up[k][x];
        y = up[k][y];
      }
    }

    const val1 = mn[0][x];
    const val2 = mn[0][y];
    if (val1 < ans) ans = val1;
    if (val2 < ans) ans = val2;
  }

  out.push(ans);
}

console.log(out.join('\n'));
